INSERT INTO `chatbot_documents` VALUES (9,'faq-shipping','faq','უფასო მიწოდება მთელი ქვეყნის მასშტაბით','მიწოდება უფასოა საქართველოს მასშტაბით.\n\nმიწოდების სავარაუდო ვადებია:\n- თბილისი: 1 სამუშაო დღე\n- რეგიონული ქალაქები: 1-3 სამუშაო დღე\n- სოფელი ან დაშორებული მისამართი: 2-5 სამუშაო დღე\n\nიმავე დღეს მიწოდება მხოლოდ გამონაკლის შემთხვევებშია შესაძლებელი და მხოლოდ წინასწარი დადასტურების შემდეგ.\n\nკურიერი, შესაძლებლობის ფარგლებში, წინასწარ დაგიკავშირდებათ მისამართის და ჩაბარების დროის დასაზუსტებლად. თუ მისამართის, ლოჯისტიკის ან სამუშაო დღის გამო დამატებითი დაზუსტება გახდა საჭირო, ვადა შეიძლება შეიცვალოს.',NULL,'{\"category\": \"მიწოდება\"}','doc_9',1,'2026-02-22 16:44:28','2026-06-30 20:40:16'),(10,'faq-warranty','faq','გარანტია','ყველა ჩვენს სმარტსაათზე ვრცელდება ოფიციალური გარანტია, რომელიც მოიცავს წარმოების დეფექტებს და დანადგარის გაუმართაობას.\n\nგარანტიის ვადა და დეტალური პირობები მითითებულია თითოეული პროდუქტის აღწერაში. თუ საათი ნორმალური გამოყენებისას გაფუჭდა, დაუკავშირდით ჩვენს მომსახურების გუნდს და ერთად ვიპოვით საუკეთესო გადაწყვეტილებას.',NULL,'{\"category\": \"გარანტია და დაბრუნება\"}','doc_10',1,'2026-02-22 16:44:28','2026-03-13 22:56:27'),(11,'faq-returns','faq','დაბრუნება და შეცვლა','ნივთის დაბრუნება შესაძლებელია მიღებიდან 7 კალენდარული დღის განმავლობაში, თუ მას შენარჩუნებული აქვს სასაქონლო იერსახე და სრული შეფუთვა.\n\nდაბრუნების პროცესის დასაწყებად დაგვიკავშირდით ერთ-ერთ საკონტაქტო არხზე და ოპერატორი დეტალურად აგიხსნით შემდეგ ნაბიჯებს.',NULL,'{\"category\": \"გარანტია და დაბრუნება\"}','doc_11',1,'2026-02-22 16:44:28','2026-03-13 22:56:28'),(12,'faq-gps','faq','GPS ფუნქციები','GPS ფუნქცია საშუალებას გაძლევთ რეალურ დროში იხილოთ თქვენი ბავშვის მდებარეობა მობილურ აპლიკაციაში.\n\nაპლიკაციიდან შეგიძლიათ ნახოთ როგორც მიმდინარე ლოკაცია, ასევე გადაადგილების ისტორია. ზოგიერთი მოდელი მხარს უჭერს უსაფრთხო ზონების (გეოფენსის) დაყენებასაც — თუ ბავშვი ამ ზონას გასცდება, მიიღებთ შეტყობინებას.',NULL,'{\"category\": \"ბავშვის უსაფრთხოება\"}','doc_12',1,'2026-02-22 16:44:28','2026-03-13 22:56:28'),(13,'faq-sim','faq','SIM ბარათის მხარდაჭერა','სიმ ბარათი საჭიროა იმისთვის, რომ საათმა შეძლოს ზარების, შეტყობინებების და მონაცემების გაგზავნა/მიღება. რეკომენდებულია აქტიური SIM ბარათი ინტერნეტის პაკეტით, რათა GPS და ონლაინ ფუნქციები სტაბილურად იმუშაოს.\n\nSIM ბარათის ჩასმის ინსტრუქცია მითითებულია საათის სახელმძღვანელოში და საჭიროების შემთხვევაში შეგვიძლია ონლაინაც დაგეხმაროთ.',NULL,'{\"category\": \"პროდუქტის გამოყენება\"}','doc_13',1,'2026-02-22 16:44:28','2026-03-13 22:56:29'),(14,'faq-battery','faq','ბატარეის დრო','ბატარეის ხანგრძლივობა დამოკიდებულია გამოყენების ინტენსივობაზე. ჩვეულებრივ, ნორმალური დატვირთვისას საათი ერთ დამუხტვაზე 1-3 დღეს მუშაობს.\n\nთუ GPS მუდმივად ჩართულია და ბევრი ზარი მიმდინარეობს, ბატარეა უფრო სწრაფად დაიხარჯება – ასეთ შემთხვევაში რეკომენდებულია ყოველდღიური დამუხტვა.',NULL,'{\"category\": \"პროდუქტის გამოყენება\"}','doc_14',1,'2026-02-22 16:44:28','2026-03-13 22:56:30'),(15,'faq-water','faq','წყალგამძლეობა','ზოგი მოდელი წყლისადმი გამძლეა ყოველდღიური გამოყენებისთვის – ხელის დაბანისას ან მსუბუქი წვიმის დროს საათის მოხსნა საჭირო არ არის.\n\nპროდუქტის გვერდზე მითითებულია ზუსტი IP მაჩვენებელი, რომელიც განსაზღვრავს, რა დონემდეა საათი დაცული წყლისგან. გთხოვთ, არ გამოიყენოთ საათი ცურვის, ზღვის ან აუზის დროს, თუ ეს პირდაპირ არ არის ნებადართული მოდელის მახასიათებლებში.',NULL,'{\"category\": \"პროდუქტის გამოყენება\"}','doc_15',1,'2026-02-22 16:44:28','2026-03-13 22:56:30'),(16,'faq-app','faq','აპლიკაციის ინსტალაცია','საათის სრულფასოვანი გამოყენებისთვის საჭიროა მობილური აპლიკაციის დაყენება მშობლის ტელეფონზე.\n\nშეკვეთასთან ერთად მიიღებთ ინსტრუქციას ჩამოტვირთვის ბმულებით. აპლიკაციაში ბავშვის საათის მიბმა მარტივია და ნაბიჯ-ნაბიჯ ინსტრუქცია ხელმისაწვდომია ქართულ ენაზე.',NULL,'{\"category\": \"აპლიკაცია და მართვა\"}','doc_16',1,'2026-02-22 16:44:28','2026-03-13 22:56:31'),(17,'faq-payments','faq','გადახდის მეთოდები','გადახდა შესაძლებელია როგორც ნაღდი ანგარიშსწორებით კურიერთან, ასევე საბანკო გადარიცხვით.\n\nშეკვეთის გაფორმების შემდეგ ოპერატორი გამოგიგზავნით დეტალურ ინფორმაციას ანგარიშის ნომრისა და გადახდის დადასტურების წესის შესახებ.',NULL,'{\"category\": \"შეკვეთა და გადახდა\"}','doc_17',1,'2026-02-22 16:44:28','2026-03-13 22:56:32'),(18,'faq-contact','faq','დახმარება და კონტაქტი','თუ კითხვები დაგრჩათ, ყოველთვის შეგიძლიათ მოგვწეროთ Facebook-ზე, WhatsApp-ზე, Instagram-ზე, ელფოსტით ან დაგვირეკოთ.\n\nკონტაქტის გვერდზე ნახავთ ყველა საკონტაქტო არხს და სამუშაო საათებს. ვეცდებით, რომ შეტყობინებებს რაც შეიძლება სწრაფად ვუპასუხოთ.',NULL,'{\"category\": \"კონტაქტი\"}','doc_18',1,'2026-02-22 16:44:28','2026-03-13 22:56:33'),(33,'contact-main','support','კონტაქტი','ტელეფონი: +995 501 44 32 65\nWhatsApp: https://wa.me/995501443265\nელფოსტა: info@mytechnic.ge\nლოკაცია: Tbilisi, Georgia\nსამუშაო საათები: ყოველდღე 09:00 - 20:00\nInstagram: https://www.instagram.com/mytechnic.store/\nFacebook: https://www.facebook.com/profile.php?id=61565719122335\nMessenger: https://m.me/61565719122335',NULL,'{\"source\": \"contact_settings\"}','doc_33',1,'2026-03-11 00:39:59','2026-06-18 16:09:38'),(34,'product-16','product','Wonlex KT34 — 4G საბავშვო სმარტ საათი GPS ტრეკერით','პროდუქტი: Wonlex KT34 — 4G საბავშვო სმარტ საათი GPS ტრეკერით\nფასი: 229.00 ლარი\nმოკლე აღწერა: Wonlex KT34 — 4G საბავშვო სმარტ საათი რეალურ დროში GPS მონიტორინგით, SOS ღილაკით, ხმოვანი და ვიდეო ზარებით. IP67 წყალგამძლეობა, გულისცემის სენსორი, ძილის მონიტორინგი. იმართება მობილური აპლიკაციით.\nაღწერა: Wonlex KT34 არის 4G საბავშვო სმარტ საათი, რომელიც მშობელს ბავშვის უსაფრთხოებაზე სრულ კონტროლს აძლევს.\r\n\r\nსაათი აღჭურვილია რეალურ დროში GPS ტრეკერით (GPS + WiFi + LBS), SOS საგანგებო ღილაკით, ხმოვანი და ვიდეო ზარის ფუნქციით. 1.85 ინჩიანი IPS სენსორული ეკრანი ნათელი და კარგად წაკითხვადია, ხოლო IP67 წყალგამძლეობის სტანდარტი საათს მტვრისა და წყლის შხეფებისგან იცავს.\r\n\r\nდამატებითი ფუნქციები: გულისცემის მონიტორი, ძილის ანალიზი, მაღვიძარა, კალენდარი და მშობლის დისტანციური მართვა აპლიკაციის საშუალებით. მხარს უჭერს Nano-SIM ბარათს. 1GB RAM + 8GB ROM მეხსიერება. კორპუსი რეზინის, სამაჯური — სილიკონის. ბატარეის ტევადობა უზრუნველყოფს 5 დღემდე მუშაობას ერთ დამუხტვაზე.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67\nბატარეა: 3-5 დღე',16,'{\"key\": \"product-16\", \"slug\": \"newest-style-4g-smart-watch-sos-call-wifi-lbs-gps-tracker-android-smart-watch-kid-sos-camera-alarm-clock-kt34\", \"price\": \"229.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"IP67\", \"battery_life_hours\": 96, \"battery_life_range\": \"3-5\"}','product#smartwatch#16',1,'2026-03-13 23:02:28','2026-06-30 20:40:16'),(35,'product-17','product','Wonlex KT20 — 4G წყალგამძლე საბავშვო სმარტ საათი','პროდუქტი: Wonlex KT20 — 4G წყალგამძლე საბავშვო სმარტ საათი\nფასი: 33.00 ლარი\nმოკლე აღწერა: Wonlex KT20 — 4G წყალგამძლე საბავშვო სმარტ საათი GPS მდებარეობით, SOS ღილაკით, ვიდეო ზარის ფუნქციით და AI ხმოვანი ასისტენტით. IP67 წყალგამძლეობა, 900mAh ბატარეა.\nაღწერა: Wonlex KT20 არის 4G საბავშვო სმარტ საათი IP67 წყალგამძლეობის სტანდარტით, რომელიც მშობელს საშუალებას აძლევს ბავშვის მდებარეობა რეალურ დროში აკონტროლოს.\r\n\r\nსაათი აღჭურვილია GPS მონიტორინგით, SOS საგანგებო ღილაკით, ხმოვანი და ვიდეო ზარის ფუნქციით, ასევე AI ხმოვანი ასისტენტით. IPS სენსორული ეკრანი უზრუნველყოფს კარგ გამოსახულებას, ხოლო 900mAh ბატარეა — გრძელვადიან მუშაობას.\r\n\r\nდამატებითი ფუნქციები: ნაბიჯებისა და კალორიების მთვლელი, ძილის მონიტორინგი, მაღვიძარა, კალენდარი, მუსიკის პლეერი და მშობლის დისტანციური მართვა. მხარს უჭერს Nano-SIM ბარათს. 1GB RAM + 8GB ROM მეხსიერება. პლასტმასის კორპუსი, სილიკონის სამაჯური.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67 წყალგაუმტარი\nბატარეა: 96 საათი',17,'{\"key\": \"product-17\", \"slug\": \"wonlex-kt20-4g-waterproof-smart-watch\", \"price\": \"33.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": 0, \"water_resistant\": \"IP67 წყალგაუმტარი\", \"battery_life_hours\": 96, \"battery_life_range\": null}','product#smartwatch#17',1,'2026-03-13 23:02:31','2026-06-30 20:40:16'),(36,'product-18','product','Wonlex CT23 — 4G საბავშვო სმარტ საათი GPS-ით','პროდუქტი: Wonlex CT23 — 4G საბავშვო სმარტ საათი GPS-ით\nფასი: 169.00 ლარი\nმოკლე აღწერა: Wonlex CT23 — ხელმისაწვდომი 4G საბავშვო სმარტ საათი GPS ტრეკერით, SOS ღილაკით და ვიდეო ზარით. IP67 წყალგამძლეობა, 1.83\" ფერადი სენსორული ეკრანი, Nano-SIM მხარდაჭერა.\nაღწერა: Wonlex CT23 არის ხელმისაწვდომი ფასის 4G საბავშვო სმარტ საათი, რომელიც ბავშვის უსაფრთხოებისთვის აუცილებელ ყველა ფუნქციას მოიცავს.\r\n\r\nსაათს აქვს GPS ტრეკერი რეალურ დროში მდებარეობის მონიტორინგისთვის, SOS საგანგებო ღილაკი, ხმოვანი და ვიდეო ზარის შესაძლებლობა. 1.83 ინჩიანი IPS ფერადი სენსორული ეკრანი (240×280) ადვილად იკითხება, ხოლო IP67 წყალგამძლეობა საათს ყოველდღიური გამოყენებისთვის მდგრადს ხდის.\r\n\r\nმხარს უჭერს Nano-SIM ბარათს. დამატებითი ფუნქციები: მაღვიძარა, კალენდარი, ძილის მონიტორინგი და მშობლის აპლიკაციიდან დისტანციური მართვის შესაძლებლობა. პლასტმასის კორპუსი, რეზინის სამაჯური. ბატარეა უძლებს 4 დღემდე.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67\nბატარეა: 2-4 დღე',18,'{\"key\": \"product-18\", \"slug\": \"wonlex-cheaper-kids-gps-smart-watch-4g-ct23\", \"price\": \"169.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"IP67\", \"battery_life_hours\": 96, \"battery_life_range\": \"2-4\"}','product#smartwatch#18',1,'2026-03-13 23:02:33','2026-06-30 20:40:16'),(37,'product-19','product','Wonlex CT27 — კომპაქტური 4G საბავშვო სმარტ საათი','პროდუქტი: Wonlex CT27 — კომპაქტური 4G საბავშვო სმარტ საათი\nფასი: 179.00 ლარი\nმოკლე აღწერა: Wonlex CT27 — კომპაქტური 4G საბავშვო სმარტ საათი GPS ტრეკერით, SOS ღილაკით, ვიდეო ზარით. მხარს უჭერს SIM და eSIM ბარათს. IP67 წყალგამძლეობა, AI ხმოვანი ასისტენტი.\nაღწერა: Wonlex CT27 არის კომპაქტური ზომის 4G საბავშვო სმარტ საათი, რომელიც სპეციალურად პატარა მაჯაზე მოხერხებულად ტარებისთვისაა შექმნილი.\r\n\r\nსაათი აღჭურვილია GPS ტრეკერით, SOS საგანგებო ღილაკით, ხმოვანი და ვიდეო ზარის ფუნქციით, ასევე AI ხმოვანი ასისტენტით. 1.83 ინჩიანი IPS სენსორული ეკრანი (240×284) ნათელი და კარგად წაკითხვადია. IP67 წყალგამძლეობის სტანდარტი საათს მტვრისა და წყლის შხეფებისგან იცავს.\r\n\r\nმთავარი უპირატესობა — SIM და eSIM ორივეს მხარდაჭერა. 730mAh ბატარეა უზრუნველყოფს 4 დღემდე მუშაობას. დამატებითი ფუნქციები: ძილის მონიტორინგი, მაღვიძარა და მშობლის აპლიკაციიდან მართვა. პლასტმასის კორპუსი, სილიკონის სამაჯური.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67\nბატარეა: 96 საათი',19,'{\"key\": \"product-19\", \"slug\": \"ct27-ultra-small-4g-rtos-gps-watch\", \"price\": \"179.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"IP67\", \"battery_life_hours\": 96, \"battery_life_range\": null}','product#smartwatch#19',1,'2026-03-13 23:02:36','2026-06-30 20:40:16'),(38,'product-20','product','Q12 — 2G საბავშვო სმარტ საათი SOS ღილაკით','პროდუქტი: Q12 — 2G საბავშვო სმარტ საათი SOS ღილაკით\nფასი: 79.00 ლარი\nმოკლე აღწერა: Q12 — ხელმისაწვდომი 2G საბავშვო სმარტ საათი SOS საგანგებო ღილაკით და LBS მდებარეობის მონიტორინგით. IP67 წყალგამძლეობა, 1.44\" სენსორული ეკრანი, SIM ბარათის მხარდაჭერა.\nაღწერა: Q12 არის ხელმისაწვდომი ფასის 2G საბავშვო სმარტ საათი, რომელიც ბავშვის უსაფრთხოების ძირითად ფუნქციებს მოიცავს.\r\n\r\nსაათს აქვს SOS საგანგებო ღილაკი, LBS მდებარეობის მონიტორინგი და ზარის განხორციელების შესაძლებლობა. 1.44 ინჩიანი TFT სენსორული ეკრანი მარტივ ინტერფეისს გვთავაზობს, რაც პატარა ბავშვებისთვის იდეალურია. IP67 წყალგამძლეობა საათს ყოველდღიური გამოყენებისთვის მდგრადს ხდის.\r\n\r\n400mAh ბატარეა უზრუნველყოფს 3 დღემდე მუშაობას. პლასტმასის კორპუსი, სილიკონის სამაჯური. კარგი არჩევანია მშობლებისთვის, რომლებსაც ბავშვის პირველი საათისთვის ძირითადი ფუნქციები სჭირდებათ.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67\nბატარეა: 1-3 დღე',20,'{\"key\": \"product-20\", \"slug\": \"high-quality-kids-smartwatch-q12-waterproof-ip67-2g-child-anti-lost-sos-call-gsm-lbs-location\", \"price\": \"79.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"IP67\", \"battery_life_hours\": 72, \"battery_life_range\": \"1-3\"}','product#smartwatch#20',1,'2026-03-13 23:02:38','2026-06-30 20:40:16'),(39,'product-21','product','Q21 — 2G წყალგამძლე საბავშვო სმარტ საათი','პროდუქტი: Q21 — 2G წყალგამძლე საბავშვო სმარტ საათი\nფასი: 79.00 ლარი\nმოკლე აღწერა: Q21 — ხელმისაწვდომი 2G წყალგამძლე საბავშვო სმარტ საათი SOS ღილაკით, LBS მდებარეობის მონიტორინგით, ზარის ფუნქციით და ტელეფონის წიგნაკით. 1.44\" სენსორული ეკრანი.\nაღწერა: Q21 არის მარტივი და საიმედო 2G საბავშვო სმარტ საათი, რომელიც ბავშვის უსაფრთხოების ძირითად საჭიროებებს ფარავს.\r\n\r\nსაათს აქვს SOS საგანგებო ღილაკი, LBS მდებარეობის მონიტორინგი, ზარის განხორციელებისა და მიღების შესაძლებლობა, ტელეფონის წიგნი და კამერა. 1.44 ინჩიანი სენსორული ეკრანი მარტივი ინტერფეისით. წყალგამძლე კორპუსი ყოველდღიური გამოყენებისთვის.\r\n\r\n400mAh ბატარეა, სრულ დამუხტვას სჭირდება დაახლოებით 2 საათი. პლასტმასის კორპუსი, სილიკონის სამაჯური. იმართება მობილური აპლიკაციით. კარგი არჩევანია, როგორც ბავშვის პირველი სმარტ საათი.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: წყალგაუმტარი\nბატარეა: 1-3 დღე',21,'{\"key\": \"product-21\", \"slug\": \"q21-children-smartwatch\", \"price\": \"79.00\", \"sale_price\": null, \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"წყალგაუმტარი\", \"battery_life_hours\": 96, \"battery_life_range\": \"1-3\"}','product#smartwatch#21',1,'2026-03-13 23:02:40','2026-06-30 20:40:16'),(40,'product-22','product','Q19 — 2G საბავშვო სმარტ საათი კამერითა და SOS-ღილაკით','პროდუქტი: Q19 — 2G საბავშვო სმარტ საათი კამერითა და SOS-ღილაკით\nფასი: 59.00 ლარი (ძველი ფასი 79.00 ლარი)\nმოკლე აღწერა: Q19 — 2G საბავშვო სმარტ საათი SIM ბრარათის მხარდაჭერით, კამერით, SOS საგანგებო ღილაკით და GPS ტრეკერით. IP67 წყალგამძლეობა, 1.44\" OLED სენსორული ეკრანი.\nაღწერა: Q19 არის 2G საბავშვო სმარტ საათი კამერით, რომელიც მშობელსა და ბავშვს შორის კომუნიკაციას მარტივს ხდის.\r\n\r\nსაათი აღჭურვილია SOS საგანგებო ღილაკით, GPS ტრეკერით და  ხმოვანი ფუნქციით. 1.44 ინჩიანი OLED სენსორული ეკრანი კარგ თვალსაჩინოებას უზრუნველყოფს, ხოლო IP67 წყალგამძლეობა საათს ყოველდღიური გამოყენებისთვის მდგრადს ხდის.\r\n\r\nდამატებითი ფუნქციები: ფიტნეს ტრეკერი, ძილის მონიტორინგი, მაღვიძარა, კალენდარი და მშობლის დისტანციური მართვა. მხარს უჭერს SIM ბარათს. პლასტმასის კორპუსი, სილიკონის სამაჯური. ბატარეა უძლებს 3 დღემდე.\nSIM მხარდაჭერა: კი\nGPS ფუნქციები: კი\nწყალგამძლეობა: IP67\nბატარეა: 1-3 დღე',22,'{\"key\": \"product-22\", \"slug\": \"2g-network-kids-smart-watch-anti-lost-sos-gps-video-call\", \"price\": \"79.00\", \"sale_price\": \"59.00\", \"sim_support\": true, \"gps_features\": true, \"warranty_months\": null, \"water_resistant\": \"IP67\", \"battery_life_hours\": null, \"battery_life_range\": \"1-3\"}','product#smartwatch#22',1,'2026-03-13 23:02:43','2026-06-30 20:40:16'),(41,'product-23','product','T53 — 4G საბავშვო სმარტ საათი ვიდეო ზარითა და GPS-ით','პროდუქტი: T53 — 4G საბავშვო სმარტ საათი ვიდეო ზარითა და GPS-ით\nფასი: 179.00 ლარი\nმოკლე აღწერა: T53 — სასაჩუქრე 4G საბავშვო სმარტ საათი ბიჭებისა და გოგოებისთვის, ვიდეო ზარით, GPS ტრეკერით, SOS ღილაკით და ფერების მიხედვით არჩევანით. კომპლექტაციაში შედის 2 ცვლადი სამაჯური და დეკორატიული ჩამოსაკიდი აქსესუარი.\nაღწერა: T53 არის სასაჩუქრე საბავშვო სმარტ საათი, რომელიც შექმნილია როგორც ყოველდღიური კომუნიკაციისთვის, ისე ბავშვის უსაფრთხოებისთვის. მოდელი გამოდგება როგორც ბიჭებისთვის, ისე გოგოებისთვის და განსაკუთრებით მიმზიდველია ფერადი დიზაინისა და კომპლექტაციაში შემავალი დამატებითი აქსესუარების გამო.\r\n\r\nსაათი აღჭურვილია 4G კავშირით, ხმოვანი და ვიდეო ზარის ფუნქციით, ასევე GPS + AGPS + LBS + WiFi ლოკაციის მხარდაჭერით, რაც მშობელს ბავშვის მდებარეობის კონტროლში ეხმარება. SOS ღილაკი დამატებით უსაფრთხოების ელემენტს ქმნის, ხოლო 1.83-ინჩიანი IPS ეკრანი გამოსახულებას მკაფიოდ აჩვენებს ყოველდღიურ გამოყენებაში.\r\n\r\nT53-ის ერთ-ერთი გამო