DROP TABLE IF EXISTS `chatbot_test_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chatbot_test_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `test_run_id` bigint unsigned NOT NULL,
  `case_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `expected_summary` text COLLATE utf8mb4_unicode_ci,
  `actual_response` text COLLATE utf8mb4_unicode_ci,
  `rag_context` longtext COLLATE utf8mb4_unicode_ci,
  `intent_json` json DEFAULT NULL,
  `standalone_query` text COLLATE utf8mb4_unicode_ci,
  `intent_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intent_confidence` decimal(6,4) DEFAULT NULL,
  `intent_latency_ms` int unsigned DEFAULT NULL,
  `status` enum('pass','fail','skip','error') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'skip',
  `keyword_match` tinyint(1) NOT NULL DEFAULT '0',
  `price_match` tinyint(1) DEFAULT NULL,
  `stock_match` tinyint(1) DEFAULT NULL,
  `guardrail_passed` tinyint(1) DEFAULT NULL,
  `georgian_qa_passed` tinyint(1) DEFAULT NULL,
  `intent_match` tinyint(1) DEFAULT NULL,
  `entity_match` tinyint(1) DEFAULT NULL,
  `llm_accuracy` tinyint unsigned DEFAULT NULL,
  `llm_relevance` tinyint unsigned DEFAULT NULL,
  `llm_grammar` tinyint unsigned DEFAULT NULL,
  `llm_completeness` tinyint unsigned DEFAULT NULL,
  `llm_safety` tinyint unsigned DEFAULT NULL,
  `llm_overall` decimal(2,1) DEFAULT NULL,
  `llm_notes` text COLLATE utf8mb4_unicode_ci,
  `response_time_ms` int unsigned DEFAULT NULL,
  `fallback_reason` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `regeneration_attempted` tinyint(1) NOT NULL DEFAULT '0',
  `regeneration_succeeded` tinyint(1) NOT NULL DEFAULT '0',
  `admin_feedback` text COLLATE utf8mb4_unicode_ci,
  `retrain_status` enum('none','pending','done') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `chatbot_test_results_test_run_id_status_index` (`test_run_id`,`status`),
  KEY `chatbot_test_results_category_index` (`category`),
  KEY `chatbot_test_results_case_id_index` (`case_id`),
  KEY `chatbot_test_results_intent_type_index` (`intent_type`),
  KEY `chatbot_test_results_fallback_reason_index` (`fallback_reason`),
  CONSTRAINT `chatbot_test_results_test_run_id_foreign` FOREIGN KEY (`test_run_id`) REFERENCES `chatbot_test_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

