DROP TABLE IF EXISTS `facebook_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `facebook_posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `media_type` enum('none','image','video') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `post_to_facebook` tinyint(1) NOT NULL DEFAULT '1',
  `post_to_instagram` tinyint(1) NOT NULL DEFAULT '0',
  `facebook_post_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram_post_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `facebook_publish_status` enum('queued','publishing','published','failed') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram_container_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram_publish_status` enum('queued','publishing','published','failed') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `facebook_error` text COLLATE utf8mb4_unicode_ci,
  `instagram_error` text COLLATE utf8mb4_unicode_ci,
  `last_publish_check_at` timestamp NULL DEFAULT NULL,
  `status` enum('draft','scheduled','published','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `ai_prompt` text COLLATE utf8mb4_unicode_ci,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `published_at` timestamp NULL DEFAULT NULL,
  `scheduled_at` timestamp NULL DEFAULT NULL,
  `fb_reactions_count` int unsigned DEFAULT NULL,
  `fb_shares_count` int unsigned DEFAULT NULL,
  `fb_impressions` bigint unsigned DEFAULT NULL,
  `ig_likes_count` int unsigned DEFAULT NULL,
  `ig_reach` bigint unsigned DEFAULT NULL,
  `metrics_fetched_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `facebook_posts_user_id_foreign` (`user_id`),
  KEY `facebook_posts_product_id_foreign` (`product_id`),
  CONSTRAINT `facebook_posts_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `facebook_posts_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
