DROP TABLE IF EXISTS `product_quality_analyses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_quality_analyses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `research_target_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `model_used` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evidence_count` int unsigned NOT NULL DEFAULT '0',
  `end_user_evidence_count` int unsigned NOT NULL DEFAULT '0',
  `supplier_evidence_count` int unsigned NOT NULL DEFAULT '0',
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `verdict` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `summary_json` json DEFAULT NULL,
  `comparison_ready_payload` json DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_quality_analyses_research_target_id_created_at_index` (`research_target_id`,`created_at`),
  KEY `product_quality_analyses_status_created_at_index` (`status`,`created_at`),
  KEY `product_quality_analyses_product_id_status_index` (`product_id`,`status`),
  CONSTRAINT `product_quality_analyses_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_quality_analyses_research_target_id_foreign` FOREIGN KEY (`research_target_id`) REFERENCES `research_targets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
