DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name_en` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ka` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `external_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_product_id` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fulfillment_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local_stock',
  `bridge_product_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bridge_product_permalink` text COLLATE utf8mb4_unicode_ci,
  `product_sync_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_synced_at` timestamp NULL DEFAULT NULL,
  `external_source_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title_ka` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title_en` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description_ka` text COLLATE utf8mb4_unicode_ci,
  `meta_description_en` text COLLATE utf8mb4_unicode_ci,
  `short_description_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description_ka` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description_en` text COLLATE utf8mb4_unicode_ci,
  `description_ka` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) DEFAULT NULL,
  `sale_price` decimal(10,2) DEFAULT NULL,
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GEL',
  `sim_support` tinyint(1) NOT NULL DEFAULT '1',
  `gps_features` tinyint(1) NOT NULL DEFAULT '1',
  `water_resistant` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_life_hours` int unsigned DEFAULT NULL,
  `battery_life_range` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `warranty_months` int unsigned DEFAULT NULL,
  `brand` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `memory_size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operating_system` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `screen_size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `screen_resolution` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_capacity_mah` int unsigned DEFAULT NULL,
  `charging_time_hours` decimal(4,1) DEFAULT NULL,
  `case_material` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `band_material` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `functions` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `home_sort_order` int unsigned NOT NULL DEFAULT '0',
  `gift_builder_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `gift_builder_role` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `gift_recipient_tags` json DEFAULT NULL,
  `gift_occasion_tags` json DEFAULT NULL,
  `gift_budget_band` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gift_compatibility_tags` json DEFAULT NULL,
  `gift_capacity_units` tinyint unsigned NOT NULL DEFAULT '1',
  `gift_badge_ka` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gift_badge_en` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gift_builder_note_ka` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gift_builder_note_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gift_sort_order` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_external_product_id_index` (`external_product_id`),
  KEY `products_active_updated_idx` (`is_active`,`updated_at`),
  KEY `products_featured_updated_idx` (`featured`,`updated_at`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

