INSERT INTO `prompt_enhancement_logs` VALUES (1,'გთხოვთ დამიწერო პოსტი სმარტ საათზე, ძაან მაგარი რო იყოს და იაფია პროსტა, ვაბშე არ ჭედავს.','გთხოვთ, დაწეროთ პროფესიონალური და ინფორმატიული პოსტი სმარტ საათის შესახებ, რომელიც გამოირჩევა მაღალი ხარისხით, ხელმისაწვდომი ფასით და საიმედო მუშაობით. პოსტი უნდა იყოს მკაფიო, მოკლე და მიზნობრივი, რათა მკითხველმა სწრაფად გაიგოს პროდუქტის უპირატესობები და მისი შეძენის სარგებელი.','{\"cultural_notes\": \"სმარტ საათის შესახებ ინფორმაციის მიწოდებისას მნიშვნელოვანია გამოყენებული იყოს ოფიციალური და პროფესიონალური ტონი, რადგან მომხმარებლები აფასებენ სანდოობას და ხარისხს. სლანგური სიტყვების ჩანაცვლება ოფიციალური ტერმინებით ზრდის პროდუქტის იმიჯს ქართულ ბაზარზე.\", \"register_applied\": \"professional\", \"grammar_corrections\": [\"გამოყვანილია ზმნისწინები და სლანგური გამოთქმები\", \"გამოყვანილია არასწორი ფორმები და შეცვლილია ფორმალური ტონის შესაბამისად\", \"დამატებულია მკაფიო და პროფესიონალური ფორმულირება\"], \"detected_dialect_or_slang\": [\"ძაან მაგარი\", \"პროსტა\", \"ვაბშე\"]}',NULL,NULL,'2026-03-19 15:12:46','2026-03-19 15:12:46'),(2,'გვაქვს 5 ახალი მოდელები და მინდა რო კლიენტებმა იყიდოს.','ჩვენ გვაქვს 5 ახალი მოდელი და მინდა, რომ კლიენტებმა ისინი იყიდონ.','{\"cultural_notes\": \"გამოიყენეთ ზუსტი და მარტივი ფორმულირება, რომელიც შეესაბამება არაოფიციალურ, მეგობრულ ტონს, თუმცა შენარჩუნებულია სისუფთავე და სისწორე ქართულ ენაში, რათა კომუნიკაცია იყოს ბუნებრივი და ადვილად გასაგები.\", \"register_applied\": \"casual\", \"grammar_corrections\": [\"შეასწორა \'მოდელები\' ერთეულში \'მოდელი\' რიცხვთან შესაბამისობისთვის\", \"შეასწორა \'მინდა რო\' ფორმა \'მინდა, რომ\'-ზე\", \"შეასწორა ზმნის ფორმა \'იყიდოს\' მრავლობითზე \'იყიდონ\' კლიენტების მიმართ\"], \"detected_dialect_or_slang\": [\"\'მინდა რო\' — არასწორი ფორმა, საჭიროა \'მინდა, რომ\'\", \"\'მოდელები\' — არასწორი მრავლობითი ფორმა რიცხვთან ერთად\", \"\'იყიდოს\' — არასწორი ზმნის ფორმა, საჭიროა მრავლობითი ფორმა \'იყიდონ\'\"]}',NULL,NULL,'2026-03-19 15:12:52','2026-03-19 15:12:52'),(3,'გუშინ კლიენტი იყიდა საათი და მინდა მადლობის პოსტი დავწერო.','გთხოვთ, შექმნათ პროფესიონალური მადლობის პოსტი, რომელიც გამოხატავს კლიენტის მიმართ მადლიერებას, რადგან გუშინ მან შეიძინა საათი. პოსტი უნდა იყოს ოფიციალური, მოკლე და დამაჯერებელი, გამოიყენეთ თქვენ ფორმა და ყურადღება მიაქციეთ სწორი გრამატიკისა და სტილის დაცვას.','{\"cultural_notes\": \"პროფესიონალურ ქართულ ბაზარზე მნიშვნელოვანია ოფიციალური და პატივისცემით სავსე ტონი, ამიტომ გამოყენებულია \'თქვენ\' ფორმა და ყურადღება გამახვილებულია მოკლე, მაგრამ დამაჯერებელ ტექსტზე, რაც ხელს უწყობს კლიენტებთან ურთიერთობის გაძლიერებას.\", \"register_applied\": \"professional\", \"grammar_corrections\": [\"დარეგულირდა ზმნის წინა ნაწილი და ფორმა შესაბამისი ფორმით (მოთხრობითი ბრუნვა საჭირო არ არის, რადგან \'იყიდა\' აქ სწორადაა გამოყენებული)\"], \"detected_dialect_or_slang\": []}',NULL,NULL,'2026-03-19 15:12:57','2026-03-19 15:12:57');
